function validate([n, presses]) {
  if (!Number.isInteger(n) || n < 1 || n > 1000) return 'n is between 1 and 1000.';
  if (!Number.isInteger(presses) || presses < 0 || presses > 1000) return 'presses is between 0 and 1000.';
  return null;
}

