function flipLights(n, presses) {
  if (presses === 0) {
    return 1;
  }
  const bulbs = Math.min(n, 3);
  if (bulbs === 1) {
    return 2;
  }
  if (bulbs === 2) {
    return presses === 1 ? 3 : 4;
  }
  if (presses === 1) {
    return 4;
  }
  return presses === 2 ? 7 : 8;
}

