function flipLights(n, presses) {
  // Track the set of reachable rows press by press; the set at a step depends only on the set before it,
  // so once it matches the set two steps earlier the sequence alternates forever.
  const groups = [
    () => true,
    label => label % 2 === 0,
    label => label % 2 === 1,
    label => label % 3 === 1
  ];
  const press = (row, button) => row.split('').map((c, i) => groups[button](i + 1) ? (c === '1' ? '0' : '1') : c).join('');
  const history = [new Set(['1'.repeat(n)])];
  for (let step = 1; step <= presses; step++) {
    const next = new Set();
    for (const row of history[step - 1]) for (let b = 0; b < 4; b++) next.add(press(row, b));
    history.push(next);
    const key = s => [...s].sort().join(',');
    if (step >= 2 && key(next) === key(history[step - 2])) {
      return (presses - step) % 2 === 0 ? next.size : history[step - 1].size;
    }
  }
  return history[presses].size;
}

